$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); . (Join-Path $PSScriptRoot 'load_relay_key.ps1'); if (Select-String -LiteralPath (Join-Path $memoryData 'config.toml') -Pattern '^llm_base_url\s*=\s*"http://127\.0\.0\.1:49376/v1"' -Quiet) { $memoryGateway=Start-Process -FilePath $memoryPythonw -ArgumentList ('"'+(Join-Path $PSScriptRoot 'relay_diagnostics_gateway.py')+'" --ensure') -WindowStyle Hidden -Wait -PassThru; if ($memoryGateway.ExitCode -ne 0) { throw 'Local model diagnostic relay failed to start.' } }; $memoryCodex=Get-ChildItem -LiteralPath (Join-Path $env:LOCALAPPDATA 'OpenAI\Codex\bin') -Directory -ErrorAction SilentlyContinue | ForEach-Object { Get-Item -LiteralPath (Join-Path $_.FullName 'codex.exe') -ErrorAction SilentlyContinue } | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1; if ($memoryCodex) { $env:AI_MEMORY_CODEX_EXECUTABLE=$memoryCodex.FullName; $env:PATH=$memoryCodex.DirectoryName+[IO.Path]::PathSeparator+$env:PATH }; $memoryArguments='--data-dir "'+$memoryData+'" --config "'+(Join-Path $memoryData 'config.toml')+'" service-host'; Start-Process -FilePath $memoryExe -ArgumentList $memoryArguments -WorkingDirectory $memoryData -WindowStyle Hidden
